import numpy as np
import os

files = [
    "basic_reduce.npy",
    "map_square.npy",
    "grad_logistic.npy",
    "scan_rnn.npy",
    "jit_mlp.npy"
]

for f in files:
    my_path = f
    ref_path = os.path.join("reference", f)

    if os.path.exists(my_path) and os.path.exists(ref_path):
        my_data = np.load(my_path)
        ref_data = np.load(ref_path)

        if my_data.shape != ref_data.shape:
            print(f"FAIL: {f} shape mismatch. Mine: {my_data.shape}, Ref: {ref_data.shape}")
        else:
            if np.allclose(my_data, ref_data, atol=1e-5):
                print(f"PASS: {f}")
            else:
                diff = np.abs(my_data - ref_data).max()
                print(f"FAIL: {f} values mismatch. Max diff: {diff}")
    else:
        print(f"Missing file for comparison: {f}")
